<script setup lang="ts">
import * as echarts from 'echarts'
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import SandboxDeviceTree from '../../components/sandbox/SandboxDeviceTree.vue'
import SandboxEditorModal from '../../components/sandbox/SandboxEditorModal.vue'
import {
  createSandbox, createSandboxRule, deleteSandbox, deleteSandboxRule,
  downloadMeasurements, downloadSandbox, editSandbox, editSandboxRule,
  fetchSandboxModels, findSandbox, findSandboxRule, importSandbox, injectFault,
  listActiveFaults, listSandboxEvents, listSandboxRules, listSandboxes,
  pauseSandbox, pauseSandboxOnLeave, setSandboxSpeed, stopFault, toggleSandbox, toggleSandboxRule,
  type ActiveFault, type Sandbox, type SandboxConfig, type SandboxEvent,
  type SandboxRule, type SandboxSensorModel,
} from '../../api/sandbox'
import { SandboxRealtimeSocket, type SandboxConnectionState, type SandboxRealtimeMessage } from '../../api/sandboxRealtime'
import type { RuleConfig } from '../../api/rule'
import { notifyError, notifyInfo, notifyWarning } from '../../utils/notification'

type ChartRow={tick:number;value:number|null}
type RuleEditorSection='info'|'target'|'condition'|'policy'|'actions'
const colors=['#2563eb','#10b981','#f59e0b','#8b5cf6','#ef4444','#06b6d4','#84cc16','#ec4899','#6366f1','#14b8a6']
const loading=ref(false),error=ref(''),notice=ref('');const sandboxes=ref<Sandbox[]>([]),selectedId=ref(''),current=ref<Sandbox|null>(null),models=ref<SandboxSensorModel[]>([]);const selectedPointIds=ref<string[]>([]),activePointId=ref(''),seriesRows=reactive(new Map<string,ChartRow[]>()),chartMode=ref<'value'|'change'>('value'),chartEl=ref<HTMLElement|null>(null);const connectionState=ref<SandboxConnectionState>('idle'),countdownUntil=ref<number|null>(null),now=ref(Date.now());const faults=ref<ActiveFault[]>([]),events=ref<SandboxEvent[]>([]),rules=ref<SandboxRule[]>([]);const sideTab=ref<'faults'|'rules'|'events'>('faults'),speeds=[1,2,5,10] as const;let chart:echarts.ECharts|null=null,resizeObserver:ResizeObserver|null=null,clockTimer:ReturnType<typeof setInterval>|null=null
const points=computed(()=>current.value?.config.terminals.flatMap(t=>t.sensors.flatMap(s=>s.points.map(p=>({...p,terminal:t.name,sensor:s.name}))))||[]),selectedPoint=computed(()=>points.value.find(p=>p.id===activePointId.value)),selectedPoints=computed(()=>selectedPointIds.value.map(id=>points.value.find(p=>p.id===id)).filter((p):p is NonNullable<typeof p>=>!!p)),hasChartData=computed(()=>selectedPointIds.value.some(id=>(seriesRows.get(id)?.length||0)>0)),countdown=computed(()=>countdownUntil.value===null?null:Math.max(0,Math.ceil((countdownUntil.value-now.value)/1000))),countdownText=computed(()=>{if(!current.value?.state)return'--';if(countdownUntil.value===null)return'--';if((countdown.value??0)>0)return`${countdown.value}s`;return now.value-countdownUntil.value>1000?'等待服务端 tick':'0s'}),connectionText=computed(()=>({idle:'未连接',connecting:'连接中',connected:'实时连接',reconnecting:'重连中',unauthorized:'无权限',closed:'已断开'}[connectionState.value])),pointName=(id:string)=>points.value.find(p=>p.id===id)?.name||id
const eventLabel:Record<string,string>={fault_started:'故障注入',fault_stopped:'故障停止',rule_triggered:'规则触发',rule_recovered:'规则恢复',virtual_action:'模拟动作'}
function applySchedule(payload:{server_time?:string;next_tick_at?:string|null}){if(!current.value?.state||!payload.next_tick_at){countdownUntil.value=null;return}const server=payload.server_time?Date.parse(payload.server_time):NaN,next=Date.parse(payload.next_tick_at);countdownUntil.value=Number.isFinite(server)&&Number.isFinite(next)?Date.now()+Math.max(0,next-server):null}
function mergeRows(pointId:string,rows:ChartRow[],replace=false){const merged=new Map<number,ChartRow>();if(!replace)for(const row of seriesRows.get(pointId)||[])merged.set(row.tick,row);for(const row of rows)merged.set(row.tick,row);seriesRows.set(pointId,[...merged.values()].sort((a,b)=>a.tick-b.tick).slice(-100))}
function showRuleWarning(title:string,message:string){notifyWarning(message,title)}
function handleRealtime(message:SandboxRealtimeMessage){if(message.type==='heartbeat')return;if(message.type==='error'){error.value=message.code==='tick_failed'?`沙盒调度异常：${message.message}`:message.message;if(message.next_tick_at)applySchedule(message);return}if(message.type==='snapshot'){current.value=message.sandbox;faults.value=message.active_faults||[];selectedPointIds.value=message.point_ids;seriesRows.clear();for(const item of message.series)mergeRows(item.point_id,item.measurements,true);if(!selectedPointIds.value.includes(activePointId.value))activePointId.value=selectedPointIds.value[0]||'';if(message.rejected_point_ids.length)error.value=`以下测点无法订阅：${message.rejected_point_ids.join('、')}`;applySchedule(message);updateListCurrent();renderChart();return}if(message.type==='sandbox_state'&&current.value){current.value.state=message.state;applySchedule(message);updateListCurrent();if(!message.state)realtime.stop();return}if(message.type==='sandbox_speed'&&current.value){current.value.config.speed=message.speed;applySchedule(message);updateListCurrent();return}if(message.type==='tick'&&current.value){current.value.tick=message.tick;applySchedule(message);for(const item of message.measurements)mergeRows(item.point_id,[{tick:item.tick,value:item.value}]);updateListCurrent();renderChart();return}if(message.type==='fault_event'||message.type==='rule_event'){events.value=[message.event,...events.value.filter(i=>i.event_id!==message.event.event_id)].slice(0,100);if(message.type==='fault_event')void refreshFaults();if(message.event.event_type==='rule_triggered'){const payload=message.event.payload;notifyError(`${pointName(payload.point_id||'')} 当前值 ${payload.value??'--'}，规则条件已满足`,payload.rule_name||'沙盒规则告警',`tick ${message.event.tick} · 沙盒模拟告警 · 未执行真实动作`)}if(message.event.event_type==='virtual_action')notice.value=`${message.event.payload.rule_name||'沙盒规则'}触发模拟动作，未执行真实任务`}}
const realtime=new SandboxRealtimeSocket({onState:s=>connectionState.value=s,onMessage:handleRealtime})
async function loadSandboxes(preferred?:string){loading.value=true;error.value='';try{const result=await listSandboxes();sandboxes.value=result.items;const next=preferred||selectedId.value||result.items[0]?.sandbox_id||'';if(selectedId.value===next)await loadCurrent();else selectedId.value=result.items.some(i=>i.sandbox_id===next)?next:(result.items[0]?.sandbox_id||'')}catch(e:any){error.value=e?.message||'加载沙盒失败'}finally{loading.value=false}}
function destroyChart(){resizeObserver?.disconnect();resizeObserver=null;chart?.dispose();chart=null}
async function ensureChart(){await nextTick();if(!chartEl.value)return;if(!chart)chart=echarts.init(chartEl.value);resizeObserver?.disconnect();resizeObserver=new ResizeObserver(()=>chart?.resize());resizeObserver.observe(chartEl.value);chart.resize();renderChart()}
async function loadCurrent(){const previous=current.value;if(previous?.state&&previous.sandbox_id!==selectedId.value){try{await pauseSandbox(previous.sandbox_id);previous.state=false}catch(e:any){error.value=e?.message||'停止原沙盒失败，已取消切换';selectedId.value=previous.sandbox_id;return}}realtime.stop(false);connectionState.value='idle';countdownUntil.value=null;seriesRows.clear();selectedPointIds.value=[];activePointId.value='';destroyChart();current.value=null;if(!selectedId.value)return;loading.value=true;try{current.value=await findSandbox(selectedId.value);const first=points.value[0]?.id||'';selectedPointIds.value=first?[first]:[];activePointId.value=first;await ensureChart();await Promise.all([refreshFaults(),refreshEvents(),refreshRules()]);if(current.value.state){realtime.subscribe(selectedPointIds.value);realtime.connect(selectedId.value)}}catch(e:any){error.value=e?.message||'加载沙盒失败'}finally{loading.value=false}}
function updateListCurrent(){if(!current.value)return;const index=sandboxes.value.findIndex(i=>i.sandbox_id===current.value?.sandbox_id);if(index>=0)sandboxes.value[index]=JSON.parse(JSON.stringify(current.value))}
watch(selectedId,()=>void loadCurrent());watch(chartMode,renderChart)
watch(error,value=>{if(value){notifyError(value);error.value=''}});watch(notice,value=>{if(value){notifyInfo(value,'沙盒模拟动作');notice.value=''}})
function togglePoint(pointId:string){const selected=selectedPointIds.value.includes(pointId);if(!selected&&selectedPointIds.value.length>=10){error.value='一次最多选择 10 个测点';return}selectedPointIds.value=selected?selectedPointIds.value.filter(id=>id!==pointId):[...selectedPointIds.value,pointId];if(selected){seriesRows.delete(pointId);if(activePointId.value===pointId)activePointId.value=selectedPointIds.value[0]||''}else{activePointId.value=pointId;seriesRows.set(pointId,[])}realtime.subscribe(selectedPointIds.value);renderChart()}
function clearPoints(){selectedPointIds.value=[];activePointId.value='';seriesRows.clear();realtime.subscribe([]);renderChart()}
function pointColor(pointId:string){const index=Math.max(0,points.value.findIndex(point=>point.id===pointId));return colors[index%colors.length]}
function latestValue(pointId:string){const rows=seriesRows.get(pointId)||[];for(let index=rows.length-1;index>=0;index--)if(rows[index]?.value!==null)return rows[index]!.value;return null}
function displayName(point:{terminal:string;sensor:string;name:string}){return`${point.terminal} / ${point.sensor} / ${point.name}`}
function chartTickRange(){const ticks=selectedPointIds.value.flatMap(id=>(seriesRows.get(id)||[]).map(row=>row.tick));if(!ticks.length)return{min:undefined,max:undefined};const min=Math.min(...ticks),max=Math.max(...ticks);return min===max?{min:Math.max(0,min-1),max:max+1}:{min,max}}
function renderChart(){if(!chartEl.value)return;chart||=echarts.init(chartEl.value);const tickRange=chartTickRange(),series=selectedPoints.value.map(point=>{const rows=seriesRows.get(point.id)||[];let values=rows.map(row=>row.value);if(chartMode.value==='change'){const numeric=values.filter((value):value is number=>value!==null);const min=numeric.length?Math.min(...numeric):0,max=numeric.length?Math.max(...numeric):0,range=max-min;values=values.map(value=>value===null?null:(range===0?50:(value-min)/range*100))}return{id:point.id,name:displayName(point),type:'line',showSymbol:false,connectNulls:false,smooth:.18,data:rows.map((row,index)=>[row.tick,values[index]]),lineStyle:{width:2.2,color:pointColor(point.id)},itemStyle:{color:pointColor(point.id)},emphasis:{focus:'series'}}});chart.setOption({animation:false,grid:{left:55,right:25,top:24,bottom:68},tooltip:{trigger:'axis',axisPointer:{type:'cross'},backgroundColor:'rgba(15,23,42,.92)',borderWidth:0,textStyle:{color:'#fff'},formatter:(params:any)=>{const items=Array.isArray(params)?params:[params],tick=items[0]?.value?.[0]??'--';return[`tick ${tick}`,...items.map((item:any)=>{const point=selectedPoints.value.find(meta=>displayName(meta)===item.seriesName),value=item.value?.[1];return`${item.marker}${point?.name||item.seriesName}：${value===null||value===undefined?'--':Number(value).toFixed(2)}${chartMode.value==='change'?'%':` ${point?.unit||''}`}`})].join('<br>')}},xAxis:{type:'value',name:'tick',scale:true,min:tickRange.min,max:tickRange.max,axisLine:{lineStyle:{color:'#cbd5e1'}},splitLine:{lineStyle:{color:'#f1f5f9'}}},yAxis:{type:'value',name:chartMode.value==='change'?'归一化趋势（%）':'数值',min:chartMode.value==='change'?0:undefined,max:chartMode.value==='change'?100:undefined,scale:chartMode.value!=='change',splitLine:{lineStyle:{color:'#edf2f7'}}},dataZoom:[{type:'inside'},{type:'slider',height:20,bottom:15}],series},true)}
async function toggleRun(){if(!current.value)return;try{const result:any=await toggleSandbox(current.value.sandbox_id);current.value.state=result.state;applySchedule(result);updateListCurrent();if(result.state){await ensureChart();realtime.subscribe(selectedPointIds.value);realtime.connect(current.value.sandbox_id)}else{realtime.stop();countdownUntil.value=null}}catch(e:any){error.value=e?.message||'运行状态切换失败'}}
async function changeSpeed(event:Event){if(!current.value)return;const speed=Number((event.target as HTMLSelectElement).value) as 1|2|5|10;try{const result:any=await setSandboxSpeed(current.value.sandbox_id,speed);current.value.config.speed=speed;applySchedule(result);updateListCurrent()}catch(e:any){error.value=e?.message||'调速失败'}}
async function removeSandbox(){if(!current.value||!confirm(`确定删除“${current.value.sandbox_name}”及全部虚拟数据吗？`))return;try{await deleteSandbox(current.value.sandbox_id);selectedId.value='';await loadSandboxes()}catch(e:any){error.value=e?.message||'删除失败'}}
const editorOpen=ref(false),editorMode=ref<'create'|'edit'>('create'),editorSaving=ref(false);function openCreate(){editorMode.value='create';editorOpen.value=true}function openEdit(){if(current.value&&!current.value.state){editorMode.value='edit';editorOpen.value=true}}
async function saveEditor(payload:{sandbox_name:string;description:string|null;config:SandboxConfig}){editorSaving.value=true;error.value='';try{const saved=editorMode.value==='create'?await createSandbox(payload):await editSandbox(current.value!.sandbox_id,payload);editorOpen.value=false;await loadSandboxes(saved.sandbox_id)}catch(e:any){error.value=e?.message||'保存沙盒失败'}finally{editorSaving.value=false}}
const importInput=ref<HTMLInputElement|null>(null);async function handleImport(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;const name=prompt('请输入导入后的沙盒名称',file.name.replace(/\.json$/i,''));if(!name){input.value='';return}try{const saved=await importSandbox(file,name,'');await loadSandboxes(saved.sandbox_id)}catch(e:any){error.value=e?.message||'导入失败'}finally{input.value=''}}
const faultForm=reactive({fault_type:'drift',value:1,duration_ticks:10,continuous:false,mode:'set'}),faultField=computed(()=>({offset:'固定偏移量',drift:'每 tick 漂移量',spike:faultForm.mode==='set'?'突变目标值':'突变叠加值',noise:'噪声标准差'}[faultForm.fault_type]||''))
async function refreshFaults(){if(current.value)faults.value=await listActiveFaults(current.value.sandbox_id).catch(()=>[])}async function addFault(){if(!current.value||!activePointId.value)return;const keys:Record<string,string>={offset:'offset',drift:'offset_per_tick',spike:'value',noise:'noise'},parameters:Record<string,number|string>={};const parameterKey=keys[faultForm.fault_type];if(faultForm.fault_type!=='stuck'&&parameterKey)parameters[parameterKey]=Number(faultForm.value);if(faultForm.fault_type==='spike')parameters.mode=faultForm.mode;try{await injectFault(current.value.sandbox_id,{fault_type:faultForm.fault_type,point_id:activePointId.value,duration_ticks:faultForm.continuous?null:Number(faultForm.duration_ticks),parameters});await refreshFaults()}catch(e:any){error.value=e?.message||'故障注入失败'}}async function endFault(item:ActiveFault){if(current.value)try{await stopFault(current.value.sandbox_id,item.event_id);await refreshFaults()}catch(e:any){error.value=e?.message||'停止故障失败'}}async function refreshEvents(){if(current.value){const result=await listSandboxEvents(current.value.sandbox_id).catch(()=>({items:[],total:0}));events.value=result.items}}async function refreshRules(){if(current.value)rules.value=await listSandboxRules(current.value.sandbox_id).catch(()=>[])}
const ruleOpen=ref(false),ruleEditId=ref(''),ruleSection=ref<RuleEditorSection>('info');type RuleCondition={operator:string;operand:string;threshold:number;samples:number;window:number};const ruleForm=reactive<{name:string;point_id:string;logic:'single'|'AND'|'OR';conditions:RuleCondition[];trigger_count:number;recovery_count:number;cooldown:number;message:string}>({name:'',point_id:'',logic:'single',conditions:[],trigger_count:1,recovery_count:1,cooldown:0,message:''});function newCondition():RuleCondition{return{operator:'GreaterThan',operand:'PointValue',threshold:30,samples:1,window:300}}
const ruleSteps=computed(()=>[{key:'info' as RuleEditorSection,title:'规则信息',summary:ruleForm.name||'设置规则名称',done:!!ruleForm.name.trim()},{key:'target' as RuleEditorSection,title:'规则监控对象',summary:pointName(ruleForm.point_id)||'选择虚拟测点',done:!!ruleForm.point_id},{key:'condition' as RuleEditorSection,title:'规则触发条件',summary:`${ruleForm.logic==='single'?'单一条件':ruleForm.logic} · ${ruleForm.conditions.length} 项`,done:ruleForm.conditions.length>0},{key:'policy' as RuleEditorSection,title:'规则触发策略',summary:`触发 ${ruleForm.trigger_count} 次`,done:Number(ruleForm.trigger_count)>0&&Number(ruleForm.recovery_count)>0},{key:'actions' as RuleEditorSection,title:'模拟告警动作',summary:'仅弹窗，不执行真实任务',done:!!ruleForm.message.trim()}])
function openRule(){if(current.value?.state){showRuleWarning('运行中不能创建规则','请先暂停当前沙盒，再新增或修改沙盒规则。');return}ruleEditId.value='';ruleSection.value='info';Object.assign(ruleForm,{name:'新沙盒规则',point_id:activePointId.value||points.value[0]?.id||'',logic:'single',conditions:[newCondition()],trigger_count:1,recovery_count:1,cooldown:0,message:'{{$.point_name}} 在 {{$.time}} 触发模拟告警，值为 {{$.value}}'});ruleOpen.value=true}
async function openRuleEdit(item:SandboxRule){if(!current.value)return;if(current.value.state){showRuleWarning('运行中不能编辑规则','请先暂停当前沙盒，再修改沙盒规则。');return}try{const detail=await findSandboxRule(current.value.sandbox_id,item.rule_id),config:any=detail.config,condition=config.condition,source=condition?.type==='Logical'?condition.children||[]:[condition];Object.assign(ruleForm,{name:config.rule_name,point_id:config.selector.point_id,logic:condition?.type==='Logical'?condition.operator:'single',conditions:source.map((node:any)=>({operator:node.operator,operand:node.left?.type||'PointValue',threshold:Number(node.right?.value??0),samples:Number(node.left?.samples??1),window:Number(node.left?.window_seconds??300)})),trigger_count:Number(config.trigger_policy?.trigger_count??1),recovery_count:Number(config.trigger_policy?.recovery_count??1),cooldown:Number(config.trigger_policy?.cooldown_seconds??0),message:config.actions?.[0]?.params?.content||''});ruleEditId.value=item.rule_id;ruleSection.value='info';ruleOpen.value=true}catch(e:any){error.value=e?.message||'读取规则失败'}}
function operand(c:RuleCondition){const base:any={type:c.operand,selector_id:'monitor'};if(c.operand==='SampleLagDifference')base.samples=Number(c.samples);if(['WindowAverageDifference','WindowRange'].includes(c.operand))base.window_seconds=Number(c.window);return base}
async function saveRule(){if(!current.value)return;if(current.value.state){ruleOpen.value=false;showRuleWarning('运行中不能保存规则','沙盒运行状态已变化，请暂停后重新编辑。');return}if(!ruleForm.name.trim()){ruleSection.value='info';return}if(!ruleForm.point_id){ruleSection.value='target';return}if(!ruleForm.conditions.length){ruleSection.value='condition';return}const nodes=ruleForm.conditions.map(c=>({type:'Comparison',operator:c.operator,left:operand(c),right:{type:'ConstantValue',value:Number(c.threshold)}})),config:RuleConfig={rule_name:ruleForm.name.trim(),description:'沙盒独立规则',selector:{selector_id:'monitor',type:'PointIdSelector',point_id:ruleForm.point_id},condition:ruleForm.logic==='single'?nodes[0]!:{type:'Logical',operator:ruleForm.logic,children:nodes},trigger_policy:{trigger_count:Number(ruleForm.trigger_count),trigger_duration_seconds:0,recovery_count:Number(ruleForm.recovery_count),recovery_duration_seconds:0,repeat_policy:'OncePerIncident',repeat_interval_seconds:null,cooldown_seconds:Number(ruleForm.cooldown),merge_window_seconds:0},actions:[{type:'LogAction',params:{level:'WARNING',content:ruleForm.message}}]};try{if(ruleEditId.value)await editSandboxRule(current.value.sandbox_id,ruleEditId.value,config);else await createSandboxRule(current.value.sandbox_id,config);ruleOpen.value=false;await refreshRules()}catch(e:any){error.value=e?.message||'保存规则失败'}}async function flipRule(item:SandboxRule){if(current.value)try{await toggleSandboxRule(current.value.sandbox_id,item.rule_id);await refreshRules()}catch(e:any){error.value=e?.message||'规则状态切换失败'}}async function removeRule(item:SandboxRule){if(current.value&&confirm(`删除规则“${item.rule_name}”？`))try{await deleteSandboxRule(current.value.sandbox_id,item.rule_id);await refreshRules()}catch(e:any){error.value=e?.message||'删除规则失败'}}
async function pauseBeforeRouteLeave(){if(!current.value?.state){realtime.stop();return true}try{await pauseSandbox(current.value.sandbox_id);current.value.state=false;countdownUntil.value=null;realtime.stop();return true}catch(e:any){error.value=e?.message||'停止沙盒失败，已取消离开页面';return false}}
function handlePageHide(){if(current.value?.state)pauseSandboxOnLeave(current.value.sandbox_id);realtime.stop(false)}
onBeforeRouteLeave(()=>pauseBeforeRouteLeave())
onMounted(async()=>{clockTimer=setInterval(()=>now.value=Date.now(),500);window.addEventListener('pagehide',handlePageHide);try{models.value=await fetchSandboxModels()}catch(e:any){error.value=e?.message||'加载传感器型号失败'}await loadSandboxes()});onBeforeUnmount(()=>{window.removeEventListener('pagehide',handlePageHide);if(current.value?.state)pauseSandboxOnLeave(current.value.sandbox_id);realtime.stop();if(clockTimer)clearInterval(clockTimer);destroyChart()})
</script>

<template><main class="page-content"><section class="workspace"><header class="page-head"><div><span>DIGITAL TWIN LAB</span><h1>数字孪生沙盒</h1><p>构建虚拟房间，验证故障、规则与分析能力</p></div><div class="head-actions"><button @click="importInput?.click()">导入配置</button><input ref="importInput" type="file" accept="application/json" hidden @change="handleImport"><button class="primary" @click="openCreate">＋ 新建沙盒</button></div></header>
<section class="control-bar"><label class="sandbox-select"><span>当前沙盒</span><select v-model="selectedId"><option value="">请选择沙盒</option><option v-for="item in sandboxes" :key="item.sandbox_id" :value="item.sandbox_id">{{item.sandbox_name}}</option></select></label><template v-if="current"><div class="divider"></div><div class="metric"><span>运行状态</span><b class="state" :class="{running:current.state}"><i></i>{{current.state?'运行中':'已暂停'}}</b></div><div class="metric"><span>实时通道</span><b class="connection" :class="connectionState"><i></i>{{connectionText}}</b></div><div class="metric tick"><span>虚拟时间</span><b>{{current.tick}} <small>tick</small></b></div><div class="metric countdown-metric"><span>下一 tick</span><b>{{countdownText}}</b></div><label class="speed"><span>运行倍速</span><select :value="current.config.speed" @change="changeSpeed"><option v-for="speed in speeds" :key="speed" :value="speed">{{speed}}× · {{30/speed}}秒</option></select></label><div class="bar-actions"><button class="run" :class="{pause:current.state}" @click="toggleRun">{{current.state?'Ⅱ 暂停':'▶ 运行'}}</button><button :disabled="current.state" @click="openEdit">编辑</button><button @click="downloadSandbox(current.sandbox_id)">导出配置</button><button @click="downloadMeasurements(current.sandbox_id)">导出数据</button><button class="danger" :disabled="current.state" @click="removeSandbox">删除</button></div></template></section>
<div v-if="!current" class="empty"><div>◇</div><h2>选择或创建一个沙盒</h2><p>沙盒数据独立存储，不会影响真实楼宇和设备</p><button class="primary" @click="openCreate">创建第一个沙盒</button></div><section v-else class="main-grid"><SandboxDeviceTree :config="current.config" :selected-point-ids="selectedPointIds" :active-point-id="activePointId" @toggle="togglePoint" @activate="activePointId=$event" @clear="clearPoints"/><section class="chart-panel"><header><div><small>已订阅 {{selectedPointIds.length}} / 10 个测点 · 最新 tick {{current.tick}}</small><h2>实时测点趋势</h2></div><div class="chart-mode"><button :class="{active:chartMode==='value'}" @click="chartMode='value'">原始数值</button><button :class="{active:chartMode==='change'}" @click="chartMode='change'">归一化趋势</button></div></header><div v-if="selectedPoints.length" class="series-legend"><button v-for="point in selectedPoints" :key="point.id" :class="{active:activePointId===point.id}" @click="activePointId=point.id"><i :style="{background:pointColor(point.id)}"></i><span><b>{{point.name}}</b><small>{{latestValue(point.id)===null?'--':latestValue(point.id)?.toFixed(2)}} {{point.unit}}</small></span></button></div><div class="chart-wrap"><div ref="chartEl" class="chart"></div><div v-if="!selectedPointIds.length" class="chart-empty"><b>请选择需要显示的测点</b><span>可在左侧同时选择最多 10 个测点</span></div><div v-else-if="!hasChartData" class="chart-empty"><b>{{current.state?'等待下一个 tick':'暂无运行数据'}}</b><span>{{current.state?`下一 tick：${countdownText}`:'运行沙盒后开始生成数据'}}</span></div></div><footer><span v-if="selectedPoint">活动测点：{{selectedPoint.name}} · 基准 {{selectedPoint.base_value}} {{selectedPoint.unit}}</span><b>1 tick = 30 秒虚拟时间</b></footer></section>
<aside class="side-panel"><nav><button :class="{active:sideTab==='faults'}" @click="sideTab='faults'">故障</button><button :class="{active:sideTab==='rules'}" @click="sideTab='rules'">规则 <i>{{rules.length}}</i></button><button :class="{active:sideTab==='events'}" @click="sideTab='events';refreshEvents()">事件</button></nav><div v-if="sideTab==='faults'" class="side-body"><div class="side-heading"><div><h3>故障注入</h3><p>目标：{{selectedPoint?.name||'未选择测点'}}</p></div><span class="safe">仅虚拟</span></div><div class="fault-form"><label><span>故障类型</span><select v-model="faultForm.fault_type"><option value="offset">固定偏移</option><option value="drift">缓慢漂移</option><option value="spike">瞬时突变</option><option value="stuck">死值</option><option value="noise">噪声增大</option></select></label><label v-if="faultForm.fault_type==='spike'"><span>突变方式</span><select v-model="faultForm.mode"><option value="set">设置为指定值</option><option value="add">在当前值上叠加</option></select></label><label v-if="faultForm.fault_type!=='stuck'"><span>{{faultField}}</span><input v-model.number="faultForm.value" type="number" step="any"></label><label class="checkbox"><input v-model="faultForm.continuous" type="checkbox"><span>持续到手动停止</span></label><label v-if="!faultForm.continuous"><span>持续时间</span><div class="unit-input"><input v-model.number="faultForm.duration_ticks" type="number" min="1"><i>tick</i></div></label><button class="inject" :disabled="!current.state||!activePointId" @click="addFault">注入故障</button><p v-if="!current.state" class="tip">沙盒运行后才能注入故障</p></div><div class="active-list"><h4>生效中的故障 <span>{{faults.length}}</span></h4><div v-if="!faults.length" class="mini-empty">当前没有活动故障</div><article v-for="item in faults" :key="item.event_id"><div><b>{{({offset:'固定偏移',drift:'缓慢漂移',spike:'瞬时突变',stuck:'死值',noise:'噪声增大'} as any)[item.fault_type]}}</b><span>{{pointName(item.point_id)}}</span><small>tick {{item.start_tick}} {{item.end_tick===null?'起':`至 ${item.end_tick}`}}</small></div><button @click="endFault(item)">停止</button></article></div></div>
<div v-else-if="sideTab==='rules'" class="side-body"><div class="side-heading"><div><h3>沙盒规则</h3><p>动作只生成模拟提示</p></div><button class="side-add" :class="{lockedButton:current.state}" :title="current.state?'请先暂停沙盒':''" @click="openRule">＋ 新增</button></div><div class="rule-list"><div v-if="!rules.length" class="mini-empty">尚未创建沙盒规则</div><article v-for="item in rules" :key="item.rule_id"><header><span :class="{on:item.state}"><i></i>{{item.state?'启用':'停用'}}</span><small>tick {{item.effective_tick}}</small></header><h4>{{item.rule_name}}</h4><p>{{pointName(item.point_id||'')}}</p><footer><button :disabled="current.state" @click="openRuleEdit(item)">编辑</button><button :disabled="current.state" @click="flipRule(item)">{{item.state?'停用':'启用'}}</button><button class="danger" :disabled="current.state" @click="removeRule(item)">删除</button></footer></article></div><p v-if="current.state" class="locked">运行中禁止创建或修改规则，请先暂停沙盒</p></div><div v-else class="side-body"><div class="side-heading"><div><h3>事件记录</h3><p>故障、规则与模拟动作</p></div><button class="side-add" @click="refreshEvents">刷新</button></div><div class="event-list"><div v-if="!events.length" class="mini-empty">暂无沙盒事件</div><article v-for="item in events" :key="item.event_id" :class="item.event_type"><i></i><div><header><b>{{eventLabel[item.event_type]||item.event_type}}</b><span>tick {{item.tick}}</span></header><p>{{item.payload.rule_name||pointName(item.payload.point_id||'')||item.payload.message||'沙盒事件'}}</p></div></article></div></div></aside></section></section></main>
<SandboxEditorModal :visible="editorOpen" :mode="editorMode" :sandbox="current" :models="models" :saving="editorSaving" @close="editorOpen=false" @submit="saveEditor"/>
<div v-if="ruleOpen" class="modal-mask" @mousedown.self="ruleOpen=false"><form class="rule-modal rule-editor-wide" @submit.prevent="saveRule"><header><div><span>SIMULATED RULE</span><h2>{{ruleEditId?'编辑':'新增'}}沙盒规则</h2><p>按模块完成规则配置，交互与规则管理保持一致</p></div><button type="button" @click="ruleOpen=false">×</button></header><div class="rule-editor-layout"><aside class="rule-overview"><div class="rule-overview-title">配置概览 <small>{{ruleSteps.filter(step=>step.done).length}} / 5</small></div><button v-for="(step,index) in ruleSteps" :key="step.key" type="button" :class="{active:ruleSection===step.key,done:step.done}" @click="ruleSection=step.key"><i>{{step.done?'✓':index+1}}</i><span><strong>{{step.title}}</strong><small>{{step.summary}}</small></span><b>›</b></button></aside><div class="rule-body rule-module-body">
<section v-if="ruleSection==='info'"><div class="rule-module-heading"><span>01</span><div><h3>规则信息</h3><p>设置用于识别这条沙盒规则的名称</p></div></div><label><span>规则名称</span><input v-model="ruleForm.name" maxlength="100" required placeholder="请输入规则名称"></label><div class="simulation-note">沙盒规则独立于生产规则，仅在当前虚拟房间中生效。</div></section>
<section v-else-if="ruleSection==='target'"><div class="rule-module-heading"><span>02</span><div><h3>规则监控对象</h3><p>只能精确选择当前沙盒中的一个虚拟测点</p></div></div><label><span>监控测点</span><select v-model="ruleForm.point_id" required><option value="">请选择虚拟测点</option><option v-for="point in points" :key="point.id" :value="point.id">{{point.terminal}} / {{point.sensor}} / {{point.name}}（{{point.unit||'无单位'}}）</option></select></label><div v-if="ruleForm.point_id" class="rule-selection-card"><b>{{pointName(ruleForm.point_id)}}</b><span>当前沙盒虚拟测点</span><small>{{points.find(point=>point.id===ruleForm.point_id)?.unit||'无单位'}}</small></div></section>
<section v-else-if="ruleSection==='condition'"><div class="rule-module-heading"><span>03</span><div><h3>规则触发条件</h3><p>配置测点值满足何种条件时产生模拟告警</p></div></div><div class="logic-row"><label><span>条件组合</span><select v-model="ruleForm.logic"><option value="single">单一条件</option><option value="AND">全部满足（AND）</option><option value="OR">任一满足（OR）</option></select></label><button v-if="ruleForm.logic!=='single'" type="button" @click="ruleForm.conditions.push(newCondition())">＋ 添加条件</button></div><section class="conditions"><article v-for="(condition,index) in ruleForm.conditions" :key="index"><i>{{index+1}}</i><select v-model="condition.operand"><option value="PointValue">当前值</option><option value="PreviousDifference">与前值差</option><option value="AbsolutePreviousDifference">与前值绝对差</option><option value="SampleLagDifference">样本间隔差</option><option value="WindowAverageDifference">窗口均值差</option><option value="WindowRange">窗口极差</option></select><input v-if="condition.operand==='SampleLagDifference'" v-model.number="condition.samples" type="number" min="1" title="样本数" placeholder="样本数"><input v-if="['WindowAverageDifference','WindowRange'].includes(condition.operand)" v-model.number="condition.window" type="number" min="1" title="窗口秒" placeholder="窗口秒"><select v-model="condition.operator"><option value="GreaterThan">大于</option><option value="GreaterThanOrEqual">大于等于</option><option value="LessThan">小于</option><option value="LessThanOrEqual">小于等于</option><option value="Equal">等于</option><option value="NotEqual">不等于</option></select><input v-model.number="condition.threshold" type="number" step="any" title="阈值" placeholder="比较常量"><button v-if="ruleForm.conditions.length>1" type="button" title="删除比较节点" @click="ruleForm.conditions.splice(index,1)">×</button></article></section></section>
<section v-else-if="ruleSection==='policy'"><div class="rule-module-heading"><span>04</span><div><h3>规则触发策略</h3><p>控制连续触发、恢复确认和告警冷却</p></div></div><div class="rule-policy-list"><label><span><b>连续触发次数</b><small>条件连续成立多少次后确认触发，避免单次波动造成误报。</small></span><input v-model.number="ruleForm.trigger_count" type="number" min="1"></label><label><span><b>连续恢复次数</b><small>条件连续不成立多少次后确认本次告警恢复。</small></span><input v-model.number="ruleForm.recovery_count" type="number" min="1"></label><label><span><b>冷却时间</b><small>一次触发后抑制再次告警的虚拟时间长度。</small></span><div class="unit-input"><input v-model.number="ruleForm.cooldown" type="number" min="0"><i>秒</i></div></label></div></section>
<section v-else><div class="rule-module-heading"><span>05</span><div><h3>模拟告警动作</h3><p>规则触发后通过右上角红色弹窗提示，不创建生产行动任务</p></div></div><label><span>告警提示内容</span><textarea v-model="ruleForm.message" maxlength="10000" rows="5" placeholder="输入模拟告警内容"></textarea></label><div class="simulation-note danger-note"><b>仅模拟执行</b><span>不发送邮件、不调用 HTTP/MQTT，也不会控制任何真实设备。</span></div></section>
</div></div><footer><button type="button" @click="ruleOpen=false">取消</button><button class="primary">保存规则</button></footer></form></div></template>

